import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { projectNotesKey, createNote } from './queries';

// Write a note on a project. useState holds only what the user is currently typing (CLAUDE.md rule
// 4); the write is a mutation that invalidates ['projects', projectId, 'notes'] so the list
// refreshes itself with the new note on top — no hand-maintained list. Blank text is not submitted
// (the server enforces the same rule).
export function NoteForm({ projectId }: { projectId: number }) {
  const [text, setText] = useState('');
  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: createNote,
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: projectNotesKey(projectId) });
      setText('');
    },
  });

  return (
    <form
      data-testid="note-form"
      onSubmit={(event) => {
        event.preventDefault();
        if (text.trim().length === 0) {
          return;
        }
        mutation.mutate({ targetType: 'project', targetId: projectId, text });
      }}
    >
      <input
        data-testid="note-form-text"
        placeholder="Write a note"
        value={text}
        onChange={(event) => setText(event.target.value)}
      />
      <button data-testid="note-form-submit" type="submit">
        Add note
      </button>
    </form>
  );
}
===== features/notes/ProjectNotesTable.tsx =====
import { useQuery } from '@tanstack/react-query';
import { projectNotesKey, fetchProjectNotes, type Note } from './queries';

// The notes written on one project. Queries for itself under ['projects', projectId, 'notes'] —
// never handed its data by a parent (CLAUDE.md rule 5). The server returns them newest first, so
// the rows render in that order untouched. Carries the stable data-testid contract: a row per note
// and the text cell the test reads.
export function ProjectNotesTable({ projectId }: { projectId: number }) {
  const { data: notes } = useQuery({
    queryKey: projectNotesKey(projectId),
    queryFn: () => fetchProjectNotes(projectId),
  });

  if (!notes) {
    return null;
  }

  return (
    <ul data-testid="project-notes-list">
      {notes.map((note: Note) => (
        <li key={note.id} data-testid={`note-row-${note.id}`}>
          <span data-testid="note-text">{note.text}</span>
          <time data-testid="note-at" dateTime={note.at}>
            {note.at}
          </time>
        </li>
      ))}
    </ul>
  );
}
